import {configuredClient,loadIdentity,authorize,readResponses,disconnect} from './google.js';
import {nextBirthday, daysUntil, parseCSV, parseBirthday, calendarFile} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const today=new Date();today.setHours(0,0,0,0);
const fmt=d=>d.toLocaleDateString('es-AR',{day:'numeric',month:'long'});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('El navegador no permite guardar cambios.');return false}}
function demo(){return ['Lucía Fernández','Martín García','Sofía Rodríguez','Tomás López','Valentina Pérez','Nicolás Romero','Camila Torres','Mateo Díaz'].map((name,i)=>{const d=new Date(today);d.setDate(d.getDate()+[0,2,5,8,12,19,37,68][i]);return {id:'demo-'+i,name,email:['lucia','martin','sofia','tomas','valentina','nicolas','camila','mateo'][i]+'@example.com',month:d.getMonth()+1,day:d.getDate()}})}
let googleLive=false,lastSync=null;
let imported=read('confetti-people',null),people=imported??demo(),reminders=read('confetti-reminders',{}),prefs=read('confetti-prefs',{before:true,on:true}),view='home',mode='list',calendarMonth=today.getMonth(),calendarYear=today.getFullYear();
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function sorted(){return people.map(p=>({...p,next:nextBirthday(p,today),days:daysUntil(p,today)})).sort((a,b)=>a.days-b.days||a.name.localeCompare(b.name,'es'))}
function initials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('')}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
const art='<div class="hero-art" aria-hidden="true"><div class="halo"></div><span class="spark s1">✦</span><span class="spark s2">✧</span><span class="spark s3">✳</span><span class="spark s4">✦</span><div class="cake"><div class="cake-base"></div><div class="cake-top"></div><div class="frost"></div><div class="frost second"></div><div class="candle"><div class="flame"></div></div></div><span class="art-caption">un día para celebrar</span></div>';
function render(){
 const all=sorted(),birthdays=all.filter(p=>p.days===0),next=all[0];
 $('#data-badge').textContent=googleLive?'Google Sheets · '+lastSync.toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'}):imported?'CSV importado · en este navegador':'Datos de ejemplo';$('#nav-count').textContent=people.length;
 $('#today-label').textContent=today.toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 $('#hero').innerHTML='<div class="hero-copy"><span class="hero-tag">'+(birthdays.length?'✦ HOY SOPLAMOS VELITAS':next?'✦ EL PRÓXIMO GRAN DÍA':'✦ EMPECEMOS A CELEBRAR')+'</span><h2>'+(birthdays.length?'¡Hoy cumple '+esc(birthdays[0].name.split(' ')[0])+'! <span>✧</span>':next?'Se viene el cumple de '+esc(next.name.split(' ')[0])+'<span>.</span>':'Cada cumpleaños merece<br>su lugar<span>.</span>')+'</h2><p>'+(birthdays.length?'Un día especial merece un lindo saludo.'+(birthdays.length>1?' Y '+(birthdays.length-1)+' persona(s) más también cumplen hoy.':'')+'<br>Tomate un momento para alegrarle el día.':next?'El '+fmt(next.next)+', en '+next.days+' día(s).<br>Un buen momento para preparar un lindo saludo.':'Importá los cumpleaños de tu equipo para empezar.')+'</p><div class="actions">'+(next?'<button class="btn" id="hero-greet">↗ '+(birthdays.length?'Enviar un saludo':'Preparar un saludo')+'</button><button class="btn white" id="hero-remind">'+(birthdays.length?'Recordá saludar en Teams':'♧ Recordarme')+'</button>':'<button class="btn" id="hero-import">＋ Agregar cumpleaños</button>')+'</div></div>'+art;
 if(next){$('#hero-greet').onclick=()=>greet(next);$('#hero-remind').onclick=()=>birthdays.length?greet(next,'teams'):remind(next)}else $('#hero-import').onclick=sources;
 $('#stats').innerHTML=[['✧',birthdays.length,'Cumplen hoy'],['▦',all.filter(p=>p.month===today.getMonth()+1).length,'Cumpleaños este mes'],['♧',Object.keys(reminders).filter(id=>people.some(p=>p.id===id)).length,'Recordatorios guardados']].map(([icon,n,label])=>'<div class="stat"><div class="stat-icon">'+icon+'</div><div><strong>'+n+'</strong><small>'+label+'</small></div></div>').join('');
 $('#breadcrumb').textContent=view==='reminders'?'Mis recordatorios':view==='calendar'?'Calendario':'Cumpleaños';
 $('#list-title').innerHTML=view==='reminders'?'Mis recordatorios <span>♧</span>':'Lo que se viene <span>↗</span>';
 $('#list-description').textContent=view==='reminders'?'Guardados en este navegador. Agregalos a tu calendario para recibir avisos.':'Un pequeño recordatorio. Un gran gesto.';
 $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 renderResults();
}
function filtered(){const query=$('#search').value.trim().toLocaleLowerCase('es'),month=Number($('#month-filter').value);return sorted().filter(p=>(!month||p.month===month)&&p.name.toLocaleLowerCase('es').includes(query)&&(view!=='reminders'||reminders[p.id]))}
function renderResults(){const rows=filtered();$('#result-count').textContent=rows.length+' personas';$$('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));
 if(mode==='calendar'){renderCalendar(rows);return}
 if(!rows.length){$('#results').innerHTML='<div class="empty"><span>✧</span>'+(view==='reminders'?'Todavía no hay recordatorios para esta búsqueda. Tocá la campanita junto a un cumpleaños.':'No encontramos cumpleaños. Probá con otro nombre o mes.')+'</div>';return}
 $('#results').innerHTML='<div class="table"><div class="table-head"><span>PERSONA</span><span>CUMPLEAÑOS</span><span>CUÁNDO</span><span style="text-align:right">UN PEQUEÑO GESTO</span></div>'+rows.map((p,i)=>'<article class="person-row"><div class="person"><span class="avatar tone'+i%5+'">'+esc(initials(p.name))+'</span><div><strong>'+esc(p.name)+'</strong><small>'+esc(p.email)+'</small></div></div><span class="birthday-date">'+fmt(new Date(2000,p.month-1,p.day))+'</span><span class="when '+(p.days===0?'today':'')+'">'+(p.days===0?'✦ ¡Es hoy!':p.days===1?'Mañana':'En '+p.days+' días')+'</span><div class="row-actions"><button class="small-btn" data-greet="'+esc(p.id)+'">↗ Saludar</button><button class="small-btn bell '+(reminders[p.id]?'saved':'')+'" data-remind="'+esc(p.id)+'" aria-label="Recordatorio para '+esc(p.name)+'" aria-pressed="'+Boolean(reminders[p.id])+'">♧</button></div></article>').join('')+'</div>';
 $$('[data-greet]').forEach(b=>b.onclick=()=>greet(people.find(p=>p.id===b.dataset.greet)));$$('[data-remind]').forEach(b=>b.onclick=()=>remind(people.find(p=>p.id===b.dataset.remind)));
}
function renderCalendar(rows){const start=(new Date(calendarYear,calendarMonth,1).getDay()+6)%7,total=new Date(calendarYear,calendarMonth+1,0).getDate();let html='<div class="calendar-top"><button class="btn white" id="prev-month" aria-label="Mes anterior">←</button><strong>'+months[calendarMonth]+' '+calendarYear+'</strong><button class="btn white" id="next-month" aria-label="Mes siguiente">→</button></div><div class="calendar-grid">'+['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'].map(d=>'<div class="week-day">'+d+'</div>').join('');for(let i=0;i<start;i++)html+='<div class="day blank"></div>';for(let d=1;d<=total;d++)html+='<div class="day '+(d===today.getDate()&&calendarMonth===today.getMonth()&&calendarYear===today.getFullYear()?'current':'')+'">'+d+rows.filter(p=>p.day===d&&p.month===calendarMonth+1).map(p=>'<button class="calendar-person" data-person="'+esc(p.id)+'">✦ '+esc(p.name)+'</button>').join('')+'</div>';$('#results').innerHTML=html+'</div>';$('#prev-month').onclick=()=>shiftMonth(-1);$('#next-month').onclick=()=>shiftMonth(1);$$('[data-person]').forEach(b=>b.onclick=()=>greet(people.find(p=>p.id===b.dataset.person)))}
function shiftMonth(amount){const d=new Date(calendarYear,calendarMonth+amount,1);calendarYear=d.getFullYear();calendarMonth=d.getMonth();renderResults()}
function greet(p,channel){openDialog('<h2>Un saludo para '+esc(p.name.split(' ')[0])+' ✦</h2><p>Unas palabras pueden hacerle el día. Personalizá tu mensaje y elegí cómo saludar.</p><label class="field" for="greeting">Tu mensaje</label><textarea id="greeting"></textarea><div class="actions"><a class="btn" id="mail-link">↗ Abrir mi correo</a><a class="btn white" id="teams-link" target="_blank" rel="noopener noreferrer">Abrir Teams</a></div><p class="help">Se abre un borrador. Vos revisás el mensaje y lo enviás desde tu cuenta.'+(!imported?' Estos datos son de ejemplo: el destinatario no es una persona real.':'')+'</p>');$('#greeting').value='¡Feliz cumple, '+p.name.split(' ')[0]+'! 🎉 Que tengas un hermoso día y un gran año por delante. ¡A celebrar!';const update=()=>{const message=$('#greeting').value;$('#mail-link').href='mailto:'+encodeURIComponent(p.email)+'?subject='+encodeURIComponent('¡Feliz cumpleaños, '+p.name.split(' ')[0]+'! 🎂')+'&body='+encodeURIComponent(message);$('#teams-link').href='https://teams.microsoft.com/l/chat/0/0?users='+encodeURIComponent(p.email)+'&message='+encodeURIComponent(message)};update();$('#greeting').oninput=update;if(channel==='teams')$('#teams-link').focus()}
function download(p,options=prefs){const blob=new Blob([calendarFile(p,today,options)],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cumple-'+p.name.replace(/[^a-z0-9]/gi,'-')+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function remind(p){const existing=reminders[p.id]??prefs;openDialog('<h2>Que no se te pase ♧</h2><p>Cumpleaños de <strong>'+esc(p.name)+'</strong> · '+fmt(new Date(2000,p.month-1,p.day))+'</p><label class="check"><input id="before" type="checkbox" '+(existing.before?'checked':'')+'> Un día antes</label><label class="check"><input id="on" type="checkbox" '+(existing.on?'checked':'')+'> El mismo día</label><div class="actions"><button class="btn" id="save-reminder">Guardar y agregar al calendario</button>'+(reminders[p.id]?'<button class="btn white" id="remove-reminder">Quitar</button>':'')+'</div><p class="help">Descargamos un evento anual con los avisos elegidos. Abrilo y guardalo en Google Calendar, Outlook o Apple Calendar para recibirlos aunque esta página esté cerrada. Verificá los avisos al importar: dependen de tu calendario.</p>');$('#save-reminder').onclick=()=>{const options={before:$('#before').checked,on:$('#on').checked};if(!options.before&&!options.on){toast('Elegí al menos un aviso.');return}reminders[p.id]=options;save('confetti-reminders',reminders);download(p,options);$('#dialog').close();render();toast('Evento descargado. Abrilo y guardalo en tu calendario.');};if($('#remove-reminder'))$('#remove-reminder').onclick=()=>{delete reminders[p.id];save('confetti-reminders',reminders);$('#dialog').close();render();toast('Quitado de esta página. Si lo importaste, borralo también de tu calendario.')};}
function settings(){openDialog('<h2>Tus recordatorios ♧</h2><p>Elegí los avisos predeterminados para los cumpleaños que agregues al calendario.</p><label class="check"><input id="pref-before" type="checkbox" '+(prefs.before?'checked':'')+'> Un día antes</label><label class="check"><input id="pref-on" type="checkbox" '+(prefs.on?'checked':'')+'> El mismo día</label><div class="actions"><button class="btn" id="save-prefs">Guardar preferencias</button><button class="btn white" id="enable-notification">Avisos con la página abierta</button></div><p class="help">Los avisos del navegador funcionan mientras esta página está abierta. Para recibir recordatorios con la página cerrada, usá los eventos de calendario. Tus preferencias quedan en este dispositivo.</p>');$('#save-prefs').onclick=()=>{prefs={before:$('#pref-before').checked,on:$('#pref-on').checked};save('confetti-prefs',prefs);$('#dialog').close();toast('Preferencias guardadas.')};$('#enable-notification').onclick=async()=>{if(!('Notification'in window)){toast('Este navegador no admite estos avisos. Usá el calendario.');return}try{const permission=await Notification.requestPermission();if(permission==='granted'){save('confetti-notify',true);toast('Avisos habilitados mientras la página esté abierta.');checkNotifications()}else toast('Sin permiso para avisos. Podés usar los eventos de calendario.')}catch{toast('No se pudieron habilitar los avisos. Usá el calendario.')}}}
function sources(){openDialog('<h2>Sumemos motivos para celebrar.</h2><p>Importá un CSV de las respuestas de Google Forms. Los datos quedan en este navegador.</p><div class="actions"><button class="btn" id="google-connect">Conectar Google Sheets</button></div><label class="field" for="csv">O importar un archivo CSV</label><input id="csv" type="file" accept=".csv,text/csv"><p class="help">Columnas: <strong>Nombre, Email, Cumpleaños</strong>. Fecha: DD/MM, DD/MM/AAAA o AAAA-MM-DD. También reconocemos “Correo electrónico” y “Fecha de cumpleaños”.</p><div class="actions"><button class="btn white" id="sample">Descargar ejemplo CSV</button>'+(imported?'<button class="btn white" id="reset-demo">Volver al ejemplo</button>':'')+'</div><p>Para la conexión automática: Google Forms → Respuestas → Vincular a Hojas de cálculo. Compartí el enlace de esa hoja en este chat para configurar el acceso privado.</p><p class="help">Conectá Google para consultar la hoja privada. Los CSV son una importación local. No necesitás publicar los correos del equipo.</p>');$('#google-connect').onclick=googleDialog;$('#sample').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFFNombre,Email,Cumpleaños\r\nAna Ejemplo,ana@example.com,25/11\r\nJuan Ejemplo,juan@example.com,03/12'],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='ejemplo-cumpleanos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#csv').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('El archivo es demasiado grande (máximo 2 MB).');const rows=parseCSV(await file.text()),normalized=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase(),headers=rows[0].map(normalized),name=headers.findIndex(s=>s.includes('nombre')),email=headers.findIndex(s=>/email|e-mail|mail|correo/.test(s)),birthday=headers.findIndex(s=>/cumple|nacimiento|birthday/.test(s));if([name,email,birthday].some(i=>i<0))throw Error('Faltan columnas de nombre, email o cumpleaños.');const unique=new Set(),data=rows.slice(1).filter(r=>r.some(s=>s.trim())).map((r,i)=>{const n=r[name]?.trim(),em=r[email]?.trim(),b=parseBirthday(r[birthday]??'');if(!n||!em||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)||!b)throw Error('Revisá el nombre, email y fecha de la fila '+(i+2)+'.');const id=em.toLowerCase();if(unique.has(id))throw Error('El correo de la fila '+(i+2)+' está duplicado.');unique.add(id);return {id,name:n,email:em,...b}});if(!data.length)throw Error('El CSV no tiene respuestas.');if(!save('confetti-people',data))return;googleLive=false;disconnect();imported=data;people=data;reminders={};save('confetti-reminders',reminders);$('#dialog').close();render();toast(data.length+' cumpleaños importados.')}catch(err){toast(err.message);e.target.value=''}};if($('#reset-demo'))$('#reset-demo').onclick=()=>{try{localStorage.removeItem('confetti-people')}catch{}googleLive=false;disconnect();imported=null;people=demo();reminders={};save('confetti-reminders',reminders);$('#dialog').close();render()}}
function checkNotifications(){if(!('Notification'in window)||Notification.permission!=='granted'||!read('confetti-notify',false))return;sorted().forEach(p=>{const options=reminders[p.id];if(!options||!((p.days===0&&options.on)||(p.days===1&&options.before)))return;const key='confetti-notified-'+today.toDateString()+'-'+p.id;if(read(key,false))return;try{new Notification(p.days===0?'¡Hoy cumple '+p.name+'! 🎉':'Mañana cumple '+p.name,{body:'Pasá por Confetti para preparar un saludo.',tag:key});save(key,true)}catch{}})}
months.forEach((month,i)=>$('#month-filter').insertAdjacentHTML('beforeend','<option value="'+(i+1)+'">'+month[0].toUpperCase()+month.slice(1)+'</option>'));
$('#search').oninput=renderResults;$('#month-filter').onchange=()=>{if($('#month-filter').value)calendarMonth=Number($('#month-filter').value)-1;renderResults()};$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;mode=view==='calendar'?'calendar':'list';$('#search').value='';$('#month-filter').value='';render()});$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;renderResults()});$('#source-button').onclick=sources;$('#data-badge').onclick=sources;$('#settings-button').onclick=settings;$('#reminder-button').onclick=settings;render();checkNotifications();setInterval(checkNotifications,60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&new Date().toDateString()!==today.toDateString())location.reload()});

function googleDialog(){
 openDialog('<h2>Cumpleaños desde Google</h2><p>Conectá una cuenta con acceso a la hoja del equipo. Solo consultamos nombre, correo y día y mes de cumpleaños. Los datos de Google permanecen en memoria durante esta sesión.</p><p class="help">Google pide permiso de lectura de tus hojas de cálculo; esta página consulta únicamente la hoja de cumpleaños configurada. Cada persona necesita acceso a esa hoja.</p>'+(!configuredClient()?'<label class="field" for="google-client">Configuración inicial · Client ID de Google</label><input id="google-client" placeholder="…apps.googleusercontent.com"><p>Se configura una sola vez por navegador. Encontrá los pasos en el README del repositorio.</p>':'')+'<div class="actions"><button class="btn" id="google-login" disabled>Cargando Google…</button>'+(googleLive?'<button class="btn white" id="google-refresh">Actualizar datos</button><button class="btn white" id="google-disconnect">Desconectar</button>':'')+'</div><p id="google-state" role="status"></p>');
 const login=$('#google-login');loadIdentity().then(()=>{if(!login.isConnected)return;login.disabled=false;login.textContent='Ingresar con Google'}).catch(error=>{if($('#google-state'))$('#google-state').textContent=error.message});
 login.onclick=async()=>{const id=$('#google-client')?.value.trim()||configuredClient();if(!/^[a-zA-Z0-9-]+\.apps\.googleusercontent\.com$/.test(id)){toast('Ingresá un Client ID válido de Google.');return}login.disabled=true;try{await authorize(id);save('confetti-google-client',id);await syncGoogle();$('#dialog').close()}catch(error){if($('#google-state'))$('#google-state').textContent=error.message}finally{login.disabled=false}};
 if($('#google-refresh'))$('#google-refresh').onclick=async()=>{const button=$('#google-refresh');button.disabled=true;try{await syncGoogle();$('#dialog').close()}catch(error){$('#google-state').textContent=error.message}finally{button.disabled=false}};
 if($('#google-disconnect'))$('#google-disconnect').onclick=()=>{disconnect();googleLive=false;people=imported??demo();lastSync=null;$('#dialog').close();render();toast('Sesión de Google desconectada.')};
}
async function syncGoogle(){
 const rows=await readResponses();const data=[],seen=new Set();for(let i=1;i<rows.length;i++){const r=rows[i];if(!r.some(v=>String(v).trim()))continue;const name=String(r[1]??'').trim(),email=String(r[2]??'').trim(),birthday=parseBirthday(r[3]??'');if(!name||!email||!birthday)throw Error('La fila '+(i+1)+' tiene datos incompletos o una fecha inválida. Se conserva la lista anterior.');const id=email.toLowerCase();if(seen.has(id))continue;seen.add(id);data.push({id,name,email,...birthday})}people=data;googleLive=true;lastSync=new Date();render();toast(data.length+' cumpleaños actualizados desde Google.');
}
